// Normalización y Enrutamiento por Temperatura y Rol
const item = $input.first().json.body || $input.first().json;

const pathname = item.pathname || '/';
const providerName = item.providerName || null;
const category = item.category || 'General';
const estimatedTotal = Number(item.estimatedTotal) || 0;
const timestamp = item.timestamp || new Date().toISOString();

let intent = 'GENERAL_INQUIRY';
let requiresHITL = false;
let priority = 'NORMAL';

if (pathname.includes('/ayuntamientos') || category.includes('B2G')) {
  intent = 'B2G_MUNICIPAL_CONTRACT';
  priority = 'HIGH';
  // Ley 5% HITL: Contratos públicos > 5.000 € requieren supervisión humana obligatoria
  if (estimatedTotal >= 5000) requiresHITL = true;
} else if (pathname.includes('/reservar/solista') || providerName === 'Edwin Agudelo') {
  intent = 'SOLISTA_RESERVATION_PRICE_LOCK';
  priority = 'HIGH';
  requiresHITL = true; // El cierre de agenda de Edwin siempre avisa al CEO
} else if (pathname.includes('/otzarreta') || category.includes('Finca')) {
  intent = 'VENUE_EXPERIENCE_EXPEDITION';
  priority = 'MEDIUM';
}

return [{
  json: {
    intent,
    priority,
    requiresHITL,
    pathname,
    providerName,
    category,
    estimatedTotal,
    timestamp,
    rawPayload: item
  }
}];

